from ute_ue.exceptions import UeProcedureError


class UcUeEndpoint:

    def __init__(self, uc_dt_base, uc_connection, ue_ip):
        """
        :param uc_dt_base:
        :param uc_connection:
        :param ue_ip:
        """
        self._uc_dt_base = uc_dt_base
        self._uc_connection = uc_connection
        self.host_device = self
        self.ue_ip = ue_ip

    def await_done(self, timeout=40):
        """:param timeout:"""
        self._uc_connection.wait_until_test_phase(self._uc_dt_base.test_id, 'completed', wait_time=timeout)

    def break_cmd(self):
        """Stops running test"""
        self._uc_connection.stop_test(imei=self._uc_dt_base.imei, test_id=self._uc_dt_base.test_id)

    def cancel(self):
        """Stops running test and waits for completed status"""
        self._uc_dt_base.stop_and_wait()

    def done(self):
        """:return: True if test is completed else False."""
        if self._uc_dt_base.get_status()['phase'] == 'completed':
            return True
        return False

    def get_client_command_object(self, endpoint_ip=None):
        """:param endpoint_ip: This is for compatibility with IperfDataTransfer"""
        return self

    def get_server_command_object(self, endpoint_ip=None):
        """:param endpoint_ip: This is for compatibility with IperfDataTransfer"""
        return self

    @staticmethod
    def has_established_connection():
        """:return: Always False because remote control is not used like with app_server"""
        return False  # Always false because no remote control like app_server has.

    def prepare_host_device(self):
        """Creates test for ultracaller if needed"""
        if not self._uc_dt_base.existing_uc_test:
            self._uc_connection.new_test(name=self._uc_dt_base.test_name, test_type='Iperf',
                                         test_params={'command': self._uc_dt_base.ue_options})

    def result(self):
        """:return: Dictionary that contains server statistics"""
        ue_result = self._uc_connection.get_test_result(self._uc_dt_base.test_id)
        return self._parse_ue_result(ue_result)

    def running(self):
        """:return: True if test is running"""
        return self._uc_dt_base.running

    def start(self, timeout=None):
        """:param timeout: This is for compatibility with IperfDataTransfer"""
        self._uc_dt_base.start_and_wait()

    def subscribe(self):
        """Subscribing to ue is not supported and raises an error"""
        raise UeProcedureError('Subscribing is not supported on {}'.format(self._uc_dt_base.direction))

    def seen_ip_of_other_endpoint(self, other_endpoint_ip):
        """:return: IP of UE host as seen by AppSvr"""
        # default is 1:1 IP as taken from  ue_host.endpoint_ip
        # but derived classes may change it
        # f.ex. if they use NAT proxy
        return other_endpoint_ip

    def _get_data_from_line(self, line):
        try:
            data = line.split(']')[1].split('  ')
            for cell in data[:]:
                if not cell:
                    data.remove(cell)
            id = int(line.split(']')[0].replace(' ', '').replace('[', ''))
            interval = data[0].replace(' ', '').split('-')
            interval = (float(interval[0]), float(data[0].split(' ')[-2].split('-')[-1]))
            transfer_raw = data[1].split(' ')
            transfer = int(float(transfer_raw[-2])) * 1024
            transfer_raw = transfer_raw[-2] + ' ' + transfer_raw[-1]
            bandwitdth_raw = data[2]
            bandwitdth = int(float(bandwitdth_raw.split(' ')[-2]) * 125)
            data_dict = {'id': id,
                         'Interval': interval,
                         'Transfer Raw': transfer_raw,
                         'Transfer': transfer,
                         'Bandwidth Raw': bandwitdth_raw,
                         'Bandwidth': bandwitdth}
            if self._uc_dt_base.protocol == 'udp' and len(data) > 4:
                data_dict['jitter'] = data[-3] if 'ms' in data[-3] else data[-4]
                data_dict['packet_loss'] = data[-1].split('(')[1].split(')')[0]
            return data_dict
        except Exception as e:
            return None

    def _parse_ue_result(self, ue_result):
        try:
            parsed_lines = []
            lines = self._get_lines(ue_result)

            for line in lines:
                data = self._get_data_from_line(line)
                if data:
                    parsed_lines.append(data)

            return self._parse_ue_result_lines(parsed_lines, self._uc_dt_base.direction)
        except Exception:
            raise UeProcedureError('Could not parse ue result.')

    def _parse_ue_result_lines(self, parsed_lines, direction):
        report = parsed_lines[-1]
        del parsed_lines[-1]
        for line in parsed_lines:
            if line['id'] != report['id']:
                parsed_lines.remove(line)
        return {'CONNECTIONS': {self._uc_dt_base.ue_stats_key: parsed_lines,
                                self._uc_dt_base.ue_report_key: {'report': report}}}

    @staticmethod
    def _get_lines(ue_result):
        for data in ue_result['data']:
            if data.get('phase') == 'completed':
                lines = data['result']['info'].splitlines()
                return lines
        return None

    @property
    def endpoint_ip(self):
        """:return: Ue's current ip"""
        return self.ue_ip

    @property
    def host_bind_interface_ip(self):
        """:return: IP of AppServer interface intended to bind to"""
        return self.endpoint_ip

    @property
    def iperf_port(self):
        """Exists for compatibility with ute_ue's IperfDataTransfer. Port should be fetched from given cmd."""
        return None
